#!/usr/bin/env bash
# Daily backups: pg_dump (custom format) of the database plus a tar of the
# exports/attachments directory, pruned after $BACKUP_KEEP_DAYS days.
# Usage: 08-backups.sh            install /usr/local/sbin/tsi-cms-backup + systemd timer
#        08-backups.sh --now      take one backup immediately (used before migrations)
# The dumps hold ciphertext only; the keys stay in $CONF_DIR and are never copied here.
. "$(dirname "$0")/lib.sh"
require_root

backup_bin=/usr/local/sbin/tsi-cms-backup

write_backup_bin() {
  cat > "$backup_bin" <<EOF
#!/usr/bin/env bash
# Generated by install-helper/08-backups.sh
set -euo pipefail
umask 077
stamp="\$(date +%Y%m%d-%H%M%S)"
dir="$BACKUP_DIR"
install -d -m 0700 "\$dir"
port="\$(pg_lsclusters --no-header | awk '\$1=="$PG_VERSION" && \$2=="main" {print \$3; exit}')"
dump="\$dir/$DB_NAME-\$stamp.dump"
(cd / && sudo -u postgres pg_dump -p "\$port" -Fc "$DB_NAME") > "\$dump"
[ -s "\$dump" ] || { echo "pg_dump produced an empty file" >&2; rm -f "\$dump"; exit 1; }
pg_restore --list "\$dump" > /dev/null  # readable archive, not just non-empty
# Grievance attachments and exports are personal data under the same retention.
tar -C "$DATA_DIR" -czf "\$dir/exports-\$stamp.tar.gz" exports
find "\$dir" -maxdepth 1 -type f \( -name '*.dump' -o -name 'exports-*.tar.gz' \) -mtime +$BACKUP_KEEP_DAYS -delete
echo "Backup written: \$dump"
EOF
  chmod 0700 "$backup_bin"
}

write_backup_bin
if [ "${1:-}" = "--now" ]; then
  "$backup_bin"
  exit 0
fi

step 'Backup timer'
cat > /etc/systemd/system/tsi-cms-backup.service <<EOF
[Unit]
Description=TSI DPDP CMS database and exports backup
After=postgresql@$PG_VERSION-main.service

[Service]
Type=oneshot
ExecStart=$backup_bin
EOF
cat > /etc/systemd/system/tsi-cms-backup.timer <<EOF
[Unit]
Description=Daily TSI DPDP CMS backup

[Timer]
OnCalendar=*-*-* $BACKUP_TIME:00
Persistent=true
RandomizedDelaySec=10m

[Install]
WantedBy=timers.target
EOF
systemctl daemon-reload
systemctl enable --now tsi-cms-backup.timer >/dev/null 2>&1
ok "Daily backup at $BACKUP_TIME to $BACKUP_DIR, kept $BACKUP_KEEP_DAYS days ($backup_bin)."
warn 'Local backups do not survive loss of this machine: copy them off-host (in India, Rule 14), and test a restore monthly.'
